import { AccountAddress, createObjectAddress, MoveString, } from "@aptos-labs/ts-sdk";
import { z, ZodError } from "zod/v4";
import { QUERY_PARAM_KEYS } from "./constants.js";
export function getMarketAddr(name, perpEngineGlobalAddr) {
    const marketNameBytes = new MoveString(name).bcsToBytes();
    return createObjectAddress(AccountAddress.fromString(perpEngineGlobalAddr), marketNameBytes);
}
/**
 * Spot market object address: `create_named_object(GlobalSpotEngine, bcs(name))`,
 * mirroring `spot_engine::register_market`.
 */
export function getSpotMarketAddr(name, deploymentPackage) {
    const globalSpotEngineAddr = createObjectAddress(AccountAddress.fromString(deploymentPackage), new TextEncoder().encode("GlobalSpotEngine"));
    const marketNameBytes = new MoveString(name).bcsToBytes();
    return createObjectAddress(globalSpotEngineAddr, marketNameBytes);
}
/**
 * Derive a market's object address from its name for the given product.
 * Perp and spot markets live under different parent objects, so the same
 * name derives DIFFERENT addresses per product — deriving with the wrong
 * product yields an address that doesn't exist on chain.
 */
export function getMarketAddrForProduct(marketName, assetType, deployment) {
    return assetType === "spot"
        ? getSpotMarketAddr(marketName, deployment.package)
        : getMarketAddr(marketName, deployment.perpEngineGlobal);
}
function getSubaccountSeedBytes(ownerAddr, seed) {
    // TODO is this the best way to concatenate  / serialize SubaccountSeed?
    return new Uint8Array([...ownerAddr.toUint8Array(), ...new MoveString(seed).bcsToBytes()]);
}
export async function postRequest({ schema, url, body, options = {}, apiKey, }) {
    return baseRequest({
        schema,
        url,
        method: "POST",
        body,
        options,
        setJsonContentType: true,
        apiKey,
    });
}
export async function patchRequest({ schema, url, body, options = {}, apiKey, }) {
    return baseRequest({
        schema,
        url,
        method: "PATCH",
        body,
        options,
        setJsonContentType: true,
        apiKey,
    });
}
export async function getRequest({ schema, url, queryParams, options = {}, apiKey, }) {
    return baseRequest({
        schema,
        url,
        method: "GET",
        queryParams,
        options,
        apiKey,
    });
}
async function baseRequest({ schema, url, method, options = {}, body, queryParams, setJsonContentType = false, apiKey, }) {
    const { headers: argHeaders, credentials, ...restOptions } = options;
    const headers = new Headers(argHeaders);
    if (setJsonContentType) {
        headers.set("Content-Type", "application/json");
    }
    if (apiKey) {
        headers.set("Authorization", `Bearer ${apiKey}`);
    }
    const queryString = queryParams ? `?${new URLSearchParams(queryParams).toString()}` : "";
    const fullUrl = `${url}${queryString}`;
    const fetchInit = {
        method,
        headers,
        credentials,
        ...restOptions,
    };
    if (body !== undefined) {
        fetchInit.body = JSON.stringify(body);
    }
    const response = await fetch(fullUrl, fetchInit);
    const { status, statusText } = response;
    if (!response.ok) {
        const data = await response.text();
        throw new FetchError({ data, status, statusText });
    }
    const textData = await response.text();
    try {
        const data = schema.parse(JSON.parse(textData, bigIntReviver));
        return { data, status, statusText };
    }
    catch (e) {
        throw prettifyMaybeZodError(e);
    }
}
export class FetchError extends Error {
    status;
    statusText;
    responseMessage;
    constructor(response, ...params) {
        // Pass remaining arguments (including vendor specific ones) to parent constructor
        super(...params);
        // Maintains proper stack trace for where our error was thrown (non-standard)
        Error.captureStackTrace(this, FetchError);
        this.status = response.status;
        try {
            const parsedData = JSON.parse(response.data);
            const parsedStatus = parsedData && typeof parsedData === "object" && "status" in parsedData
                ? parsedData.status
                : undefined;
            const parsedMessage = parsedData && typeof parsedData === "object" && "message" in parsedData
                ? parsedData.message
                : undefined;
            this.statusText = typeof parsedStatus === "string" ? parsedStatus : response.statusText;
            this.responseMessage = typeof parsedMessage === "string" ? parsedMessage : response.data;
        }
        catch {
            this.statusText = response.statusText;
            this.responseMessage = response.data;
        }
        const formattedStatusText = this.statusText ? ` (${this.statusText})` : "";
        this.message = `HTTP Error ${this.status}${formattedStatusText}: ${this.responseMessage}`;
    }
}
export function prettifyMaybeZodError(e) {
    if (e instanceof ZodError) {
        return new Error(z.prettifyError(e), { cause: e });
    }
    return e;
}
export function bigIntReviver(key, value) {
    if (value &&
        typeof value === "object" &&
        "$bigint" in value &&
        typeof value.$bigint === "string") {
        return BigInt(value.$bigint);
    }
    return value;
}
export function getPrimarySubaccountAddr(addr, compatVersion, package_addr) {
    const account = typeof addr === "string" ? AccountAddress.fromString(addr) : addr;
    const package_address = typeof package_addr === "string" ? AccountAddress.fromString(package_addr) : package_addr;
    const deriver = createObjectAddress(package_address, new TextEncoder().encode("GlobalSubaccountManager"));
    const res = createObjectAddress(deriver, getSubaccountSeedBytes(account, "primary_subaccount")).toString();
    return res;
}
export function getTradingCompetitionSubaccountAddr(addr) {
    const account = typeof addr === "string" ? AccountAddress.fromString(addr) : addr;
    const seed = new TextEncoder().encode("trading_competition");
    return createObjectAddress(account, seed).toString();
}
export function getVaultShareAddress(vaultAddress) {
    const seed = new TextEncoder().encode("vault_share_asset");
    return createObjectAddress(AccountAddress.fromString(vaultAddress), seed).toString();
}
export const PARAM_MAP = {
    limit: QUERY_PARAM_KEYS.limit,
    offset: QUERY_PARAM_KEYS.offset,
    sortKey: QUERY_PARAM_KEYS.sortKey,
    sortDir: QUERY_PARAM_KEYS.sortDir,
    searchTerm: QUERY_PARAM_KEYS.searchTerm,
};
/**
 * Construct query params from an args object, supporting optional PageParams, SearchTermParams, and generic SortParams.
 * @param args - The argument object, which may include page, search, and sort params.
 * @returns URLSearchParams instance with the constructed query parameters.
 */
export function constructKnownQueryParams(args) {
    const queryParams = new URLSearchParams();
    Object.keys(args).forEach((_argKey) => {
        const argKey = _argKey;
        const value = args[argKey];
        const paramKey = PARAM_MAP[argKey];
        if (paramKey && value !== undefined && !(typeof value === "string" && value.trim() === "")) {
            queryParams.set(paramKey, String(value));
        }
    });
    return queryParams;
}
export function generateRandomReplayProtectionNonce() {
    const buf = new Uint32Array(2);
    crypto.getRandomValues(buf);
    const valueAtIndex0 = buf[0];
    const valueAtIndex1 = buf[1];
    if (!valueAtIndex0 || !valueAtIndex1)
        return null;
    // combine two 32-bit parts into a single 64-bit bigint
    return (BigInt(valueAtIndex0) << BigInt(32)) | BigInt(valueAtIndex1);
}
/**
 * Round price to valid tick size.
 * Prices must be multiples of tickSize in chain units.
 */
export function roundToTickSize(price, tickSize, pxDecimals, roundUp) {
    if (price === 0)
        return 0;
    const denormalized = price * 10 ** pxDecimals;
    const rounded = roundUp
        ? Math.ceil(denormalized / tickSize) * tickSize
        : Math.floor(denormalized / tickSize) * tickSize;
    return Number((rounded / 10 ** pxDecimals).toFixed(pxDecimals));
}
export const extractVaultAddressFromCreateTx = (createVaultTx) => {
    // Extract vault address from transaction events
    let vaultAddress = null;
    if ("events" in createVaultTx && Array.isArray(createVaultTx.events)) {
        for (const event of createVaultTx.events) {
            if (event.type.includes("::vault::VaultCreatedEvent")) {
                const eventData = event.data;
                vaultAddress = eventData.vault;
                break;
            }
        }
    }
    if (!vaultAddress)
        throw new Error("Unable to extract vault address from transaction");
    vaultAddress =
        typeof vaultAddress === "object" && "inner" in vaultAddress ? vaultAddress.inner : vaultAddress;
    return vaultAddress;
};
